"""The UDM Pro's FRR config, which it has no API for, so it is pasted in by hand."""

import ipaddress

HEADER = (
    "! GENERATED by 'homelab generate' from NetBox. Do not hand-edit.\n"
    "! Re-run it after changing NetBox; `--check` reports drift.\n"
)


def frr_config(site: dict) -> str:
    # An identifier, not an address to reach - but one the router demonstrably holds
    router_id = min(
        (v for v in site["vlans"].values() if v["gateway_ipv4"]), key=lambda v: v["vid"]
    )["gateway_ipv4"]
    lines = [
        HEADER,
        f"router bgp {site['router_asn']}",
        f" bgp router-id {router_id}",
        " bgp log-neighbor-changes",
        " bgp ebgp-requires-policy",
        " no bgp default ipv4-unicast",
    ]

    # A speaker that can set an IPv6 next hop on an IPv4 session (FRR) sends both families
    # there; one that can't (Talos's GoBGP) sends IPv6 on an IPv6 session of its own, since
    # this kernel installs no IPv6 route via an IPv4 next hop. Groups share a range under their
    # own ASNs, so every peer group is `remote-as external`.
    groups = site["peer_groups"]
    for g in groups:
        lines += [" !", f" neighbor {g['name']} peer-group", f" neighbor {g['name']} remote-as external"]
        keepalive, holdtime = g["timers"]
        if keepalive:
            lines.append(f" neighbor {g['name']} timers {keepalive} {holdtime}")
        lines += [f" bgp listen range {r} peer-group {g['name']}" for r in g["ranges"]]

    for family in ("ipv4", "ipv6"):
        lines += [" !", f" address-family {family} unicast"]
        for g in groups:
            if family not in g["families"]:
                continue
            lines += [
                f"  neighbor {g['name']} activate",
                f"  neighbor {g['name']} soft-reconfiguration inbound",
                f"  neighbor {g['name']} maximum-prefix {g['max_prefixes']}",
                f"  neighbor {g['name']} route-map FROM-{g['name']} in",
                *(f"  neighbor {g['name']} route-map {policy} out" for policy in g["export"]),
            ]
        lines += ["  maximum-paths 8", " exit-address-family"]
    lines.append("!")

    for name in sorted({policy for g in groups for policy in g["export"]}):
        for index, action in site["policies"][name]:
            lines += [f"route-map {name} {action} {index}", "exit", "!"]

    # What GoBGP sends IPv6 routes with over an IPv4 session: never installable here, and
    # never to be chosen over the same route from its IPv6 session
    lines += ["ipv6 prefix-list IPV4-MAPPED seq 5 permit ::ffff:0:0/96 le 128", "!"]

    # Inside what the speaker group originates, and first in the AS path whatever internal
    # ASNs follow
    peering = sorted({asn for g in groups for asn in g["speakers"]})
    for asn in peering:
        nets = _owned(site["speakers"][asn])
        lines += _prefix_list("ip", f"SPEAKER-{asn}-V4", nets[4])
        lines += _prefix_list("ipv6", f"SPEAKER-{asn}-V6", nets[6])
        lines += [f"bgp as-path access-list SPEAKER-{asn} permit ^{asn}_", "!"]

    # A peer group accepts only the speaker groups with a session on it. One route-map serves
    # both families: an IPv4 prefix-list never matches an IPv6 route, nor the reverse
    for g in groups:
        route_map = f"FROM-{g['name']}"
        lines += [f"route-map {route_map} deny 5", " match ipv6 next-hop prefix-list IPV4-MAPPED", "exit", "!"]
        seq = 0
        for family, suffix, version in (("ip", "V4", 4), ("ipv6", "V6", 6)):
            if f"ipv{version}" not in g["families"]:
                continue
            for asn in g["speakers"]:
                if not _owned(site["speakers"][asn])[version]:
                    continue
                seq += 10
                lines += [
                    f"route-map {route_map} permit {seq}",
                    f" match {family} address prefix-list SPEAKER-{asn}-{suffix}",
                    f" match as-path SPEAKER-{asn}",
                    "exit",
                    "!",
                ]

    return "\n".join(lines) + "\n"


def _owned(speaker: dict) -> dict:
    """A block allows anything inside it, so a sub-pool of it adds nothing; an assigned address
    allows only itself."""
    nets = {4: [], 6: []}
    blocks = [ipaddress.ip_network(cidr) for cidr in speaker["prefixes"]]
    for version in nets:
        for net in ipaddress.collapse_addresses(n for n in blocks if n.version == version):
            nets[version].append(f"{net} le {net.max_prefixlen}")
    for address in speaker["addresses"]:
        ip = ipaddress.ip_address(address)
        nets[ip.version].append(f"{ip}/{ip.max_prefixlen}")
    return nets


def _prefix_list(family: str, name: str, entries: list) -> list[str]:
    if not entries:
        return []
    return [
        f"{family} prefix-list {name} seq {seq * 5} permit {entry}"
        for seq, entry in enumerate(entries, start=1)
    ] + ["!"]
